const path = (msg.req && (msg.req.path || msg.req.url)) || '';

// Asset-like requests (anything with a file extension) should not
// masquerade as HTML. UIBUILDER's static would have served it if it
// existed; if we got here it doesn't, so return a clean 404.
if (/\.[a-zA-Z0-9]+$/.test(path)) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
    msg.payload = 'Not Found';
    return [null, msg];
}

// Otherwise: route to the file reader, which will load index.html.
msg.filename = '/data/uibuilder/aiInsight/src/index.html';
return [msg, null];

// On read failure, file-in sets msg.error / no payload — surface as 503.
if (typeof msg.payload !== 'string' || msg.payload.length === 0) {
    msg.statusCode = 503;
    msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
    msg.payload = 'SPA bundle not deployed';
    return msg;
}
msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'no-cache, no-store, must-revalidate'
};
return msg;
